// WF25 sombra: un aviso de Tokko (correo de notifier@tokkobroker.com) -> una fila.
const decode = (s) => s
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const toText = (s) => decode(String(s)
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|li|tr|div)>/gi, '\n')
  .replace(/<[^>]+>/g, ''));
const pick = (re, s) => { const m = s.match(re); return m ? m[1].trim() : null; };
const e164 = (raw) => {
  if (!raw) return null;
  const digits = raw.replace(/\D/g, '');
  if (/^\d{10}$/.test(digits)) return '+52' + digits;
  return /^[1-9]\d{7,14}$/.test(digits) ? '+' + digits : null;
};

return $input.all().map(({ json: j }) => {
  const raw = String(j.html || j.text || '');
  const t = toText(raw);
  const tags = (pick(/Etiquetas:[ \t]*([^\n]+)/, t) || '').split(',').map((x) => x.trim()).filter(Boolean);
  const phone = e164(pick(/M[oó]vil:[ \t]*(\+?[\d ()-]{8,})/, t)) || e164(pick(/Tel[eé]fono:[ \t]*(\+?[\d ()-]{8,})/, t));
  const email = (pick(/Correo electr[oó]nico:[ \t]*(\S+@\S+)/, t) || '').toLowerCase() || null;
  const ebRef = (pick(/Ref:\s*(EB-[A-Za-z0-9]+)/, t) || '').toUpperCase() || null;
  const message = (pick(/Mensaje:\s*([\s\S]*?)\n\s*Propiedades\/Desarrollos/, t) || pick(/Mensaje:\s*([\s\S]*)/, t) || '')
    .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 2000) || null;
  return { json: {
    gmail_message_id: j.id,
    received_at: j.date || null,
    subject: j.subject || null,
    webcontact_id: pick(/webcontact\/(\d+)/, raw),
    portal: tags[0] || null,
    kind: tags.find((x) => /^(Consulta|Contacto por Whatsapp)$/i.test(x)) || null,
    tags: tags.join(', ') || null,
    lead_name: pick(/Hay una nueva consulta de[ \t]*([^\n]+)/, t),
    phone,
    email,
    eb_ref: ebRef,
    i24_listing_id: pick(/inmuebles24\.com\/propiedades\/[^\s"'<>]*?(\d{6,})\.html/, t),
    property_title: (pick(/Propiedades:\s*\n\s*([^\n]+)/, t) || '').replace(/\s+/g, ' ') || null,
    message,
    parse_ok: Boolean((phone || email) && ebRef),
  } };
});
